local M = class("FulwinArenaInvitePopModel", LikeOO.OODataBase)

M.point = {}

function M:onCreate()
    self.m_transfer = "scale"
    self.m_version = self.m_params.version
    self.m_selectPeopleCount = 1
    local saveJusticeIndex = UserDataManager.local_data:getUserDataByKey("fulwin_arena_is_justice",-1)
    if saveJusticeIndex == -1 then
        self:modifyJusticeData(false)
    else
        self.m_isJustice = saveJusticeIndex == 1
    end
    -- 对手信息
    self.m_rivalData = nil
    self:getData("friend_arena_index")
end

function M:modifyJusticeData(isJustice)
    self.m_isJustice = isJustice
    local justicIndex = isJustice and 1 or 0
    UserDataManager.local_data:setUserDataByKey("fulwin_arena_is_justice", justicIndex)
end

function M:setRivalData(rivalData)
    self.m_rivalData = rivalData
end

function M:setSelectPeopleCount(selectPeopleCount)
    self.m_selectPeopleCount = selectPeopleCount
end

function M:getRewardsData()
    local tempData = {}
    local tempList = {}
    local wish_rewardData = ConfigManager:getCfgByName("egg")
    versionData = wish_rewardData[self.m_version] or {}
    for index, itemData in pairs(versionData) do
        tempList[index] = {
            awardData = itemData.reward[1],
            weight = itemData.show_weight or 0,
        }
    end
    return tempList
end

function M:onEnter()
    self.m_myZfljRank = self.m_data.arena_rank
    self.m_myTxywRank = self.m_data.high_arena_rank
end

return M